use bevy::{audio::Volume, prelude::*};

use crate::{enemy::Enemy, player::Player, rng::Rng, Game, Phase};

pub type Set = Vec<Handle<AudioSource>>;

/// Every sound the game uses. Files are generated by `tools/generate_audio.py`.
#[derive(Resource)]
pub struct Sfx {
    pub shotgun: Set,
    pub reload: Handle<AudioSource>,
    pub dry_fire: Handle<AudioSource>,
    pub step_mud: Set,
    pub player_hurt: Set,
    pub heartbeat: Handle<AudioSource>,
    pub flesh_hit: Set,
    pub groan: Set,
    pub groan_far: Set,
    pub snarl: Set,
    pub attack: Set,
    pub hurt: Set,
    pub death: Set,
    pub ghoul_step: Set,
    pub bone_rattle: Set,
    pub bone_step: Set,
    pub bone_hit: Set,
    pub bone_collapse: Set,
    pub skull_wail: Handle<AudioSource>,
    pub rain: Handle<AudioSource>,
    pub wind: Handle<AudioSource>,
    pub drone: Handle<AudioSource>,
    pub fire: Handle<AudioSource>,
    pub thunder: Set,
    pub burst: Handle<AudioSource>,
    pub wave_start: Handle<AudioSource>,
    pub wave_clear: Handle<AudioSource>,
    pub pickup: Handle<AudioSource>,
}

fn set(assets: &AssetServer, base: &str, n: usize) -> Set {
    (1..=n)
        .map(|i| assets.load(format!("audio/{base}_{i}.wav")))
        .collect()
}

fn load_sfx(mut commands: Commands, assets: Res<AssetServer>) {
    let one = |name: &str| assets.load(format!("audio/{name}.wav"));
    commands.insert_resource(Sfx {
        shotgun: set(&assets, "shotgun", 4),
        reload: one("shotgun_reload"),
        dry_fire: one("dry_fire"),
        step_mud: set(&assets, "step_mud", 4),
        player_hurt: set(&assets, "player_hurt", 2),
        heartbeat: one("heartbeat"),
        flesh_hit: set(&assets, "flesh_hit", 3),
        groan: set(&assets, "undead_groan", 4),
        groan_far: set(&assets, "undead_groan_far", 4),
        snarl: set(&assets, "undead_snarl", 2),
        attack: set(&assets, "undead_attack", 2),
        hurt: set(&assets, "undead_hurt", 3),
        death: set(&assets, "undead_death", 2),
        ghoul_step: set(&assets, "ghoul_step", 3),
        bone_rattle: set(&assets, "bone_rattle", 3),
        bone_step: set(&assets, "bone_step", 3),
        bone_hit: set(&assets, "bone_hit", 3),
        bone_collapse: set(&assets, "bone_collapse", 2),
        skull_wail: one("skull_wail"),
        rain: one("rain_loop"),
        wind: one("wind_loop"),
        drone: one("drone_loop"),
        fire: one("fire_loop"),
        thunder: set(&assets, "thunder", 3),
        burst: one("burst"),
        wave_start: one("wave_start"),
        wave_clear: one("wave_clear"),
        pickup: one("pickup"),
    });
}

pub fn pick(set: &Set, rng: &mut Rng) -> Handle<AudioSource> {
    set[rng.index(set.len())].clone()
}

fn settings(game: &Game, volume: f32, speed: f32, spatial: bool) -> PlaybackSettings {
    let mut s = PlaybackSettings::DESPAWN
        .with_volume(Volume::Linear(volume))
        .with_speed(speed)
        .with_spatial(spatial);
    s.muted = game.muted;
    s
}

/// Non-positional sound (player weapon, own body, UI stingers).
pub fn play_2d(
    commands: &mut Commands,
    game: &Game,
    sound: Handle<AudioSource>,
    volume: f32,
    speed: f32,
) {
    commands.spawn((
        AudioPlayer::new(sound),
        settings(game, volume, speed, false),
    ));
}

/// Positional one-shot fixed in the world.
pub fn play_at(
    commands: &mut Commands,
    game: &Game,
    sound: Handle<AudioSource>,
    pos: Vec3,
    volume: f32,
    speed: f32,
) {
    commands.spawn((
        AudioPlayer::new(sound),
        settings(game, volume, speed, true),
        Transform::from_translation(pos),
    ));
}

/// Positional one-shot that follows an entity (voices and steps stay attached to the body).
pub fn play_on(
    commands: &mut Commands,
    game: &Game,
    parent: Entity,
    offset: Vec3,
    sound: Handle<AudioSource>,
    volume: f32,
    speed: f32,
) {
    let id = commands
        .spawn((
            AudioPlayer::new(sound),
            settings(game, volume, speed, true),
            Transform::from_translation(offset),
        ))
        .id();
    commands.entity(parent).add_child(id);
}

#[derive(Component)]
struct DroneLoop;
#[derive(Component)]
struct HeartLoop;
#[derive(Component)]
struct WindLoop;

/// 0 = calm, 1 = enemies on top of the player. Drives the ambient layers.
#[derive(Resource, Default)]
pub struct Tension(pub f32);

fn start_ambience(mut commands: Commands, sfx: Res<Sfx>) {
    let looped = |v: f32| PlaybackSettings::LOOP.with_volume(Volume::Linear(v));
    commands.spawn((AudioPlayer::new(sfx.rain.clone()), looped(0.55)));
    commands.spawn((AudioPlayer::new(sfx.wind.clone()), looped(0.3), WindLoop));
    commands.spawn((AudioPlayer::new(sfx.drone.clone()), looped(0.12), DroneLoop));
    commands.spawn((
        AudioPlayer::new(sfx.heartbeat.clone()),
        looped(0.0),
        HeartLoop,
    ));
}

fn director(
    time: Res<Time>,
    game: Res<Game>,
    mut tension: ResMut<Tension>,
    players: Query<&GlobalTransform, With<Player>>,
    enemies: Query<(&GlobalTransform, &Enemy)>,
    mut drone: Query<&mut AudioSink, (With<DroneLoop>, Without<HeartLoop>, Without<WindLoop>)>,
    mut heart: Query<&mut AudioSink, (With<HeartLoop>, Without<DroneLoop>, Without<WindLoop>)>,
    mut wind: Query<&mut AudioSink, (With<WindLoop>, Without<DroneLoop>, Without<HeartLoop>)>,
) {
    let Ok(player) = players.single() else {
        return;
    };
    let p = player.translation();
    let mut target = 0.0f32;
    let mut alive = 0;
    if game.phase == Phase::Fighting {
        for (t, e) in &enemies {
            if !e.alive() {
                continue;
            }
            alive += 1;
            let d = t.translation().distance(p);
            target = target.max((1.0 - (d - 2.0) / 16.0).clamp(0.0, 1.0));
        }
        target = (target + alive as f32 * 0.03).min(1.0);
    }
    let low_hp = (1.0 - game.hp / 40.0).clamp(0.0, 1.0);
    target = target.max(low_hp * 0.8);
    let rate = if target > tension.0 { 1.5 } else { 0.35 };
    tension.0 += (target - tension.0) * (rate * time.delta_secs()).min(1.0);
    let t = tension.0;
    if let Ok(mut s) = drone.single_mut() {
        s.set_volume(Volume::Linear(0.1 + 0.5 * t));
        s.set_speed(0.92 + 0.14 * t);
    }
    if let Ok(mut s) = wind.single_mut() {
        s.set_volume(Volume::Linear(0.32 - 0.14 * t));
    }
    if let Ok(mut s) = heart.single_mut() {
        let alive_player = game.hp > 0.0;
        let v = if alive_player {
            low_hp * 0.9 + t * 0.15
        } else {
            0.0
        };
        s.set_volume(Volume::Linear(v));
        s.set_speed(1.0 + (1.0 - game.hp / 100.0) * 0.45);
    }
}

pub struct AudioDirectorPlugin;

impl Plugin for AudioDirectorPlugin {
    fn build(&self, app: &mut App) {
        app.init_resource::<Tension>()
            .add_systems(PreStartup, load_sfx)
            .add_systems(Startup, start_ambience)
            .add_systems(Update, director);
    }
}
